from __future__ import annotations

"""The host allowlist and how a host is matched against it.

The allowlist is a set of permitted hostnames. A host is permitted only when it
*is* one of those names — not when it merely resembles one. Two attacker tricks
make a loose match dangerous:

* **Suffix confusion.** ``api.allowed.com.evil.tld`` ends with nothing the
  allowlist owns, but ``evil.tld`` controls it. A naive "does the host end with
  an allowlisted name" check is wrong on its own; the only safe relationship is
  full-name equality (subdomain rules, when wanted, are an explicit separate
  thing, not an accident of string suffixes).
* **Prefix / substring confusion.** ``evilapi.allowed.com`` contains
  ``api.allowed.com`` only if you squint; ``allowed.com.attacker.net`` contains
  ``allowed.com``. A ``in`` / ``startswith`` / ``endswith`` test accepts hosts
  the allowlist never authorized.

The allowlist stores canonical names (lowercased, no trailing dot, punycode).
An incoming host is canonicalized the same way before it is compared, so a
match is decided on equal canonical names. Membership is therefore an exact set
lookup, nothing fuzzier.
"""

from hostname import HostnameError, canonicalize_hostname


class Allowlist:
    """A set of exactly-permitted canonical hostnames."""

    def __init__(self, hosts: list[str] | tuple[str, ...] | None = None) -> None:
        self._hosts: set[str] = set()
        for host in hosts or ():
            self.add(host)

    def add(self, host: str) -> None:
        """Add *host* to the allowlist in canonical form."""

        try:
            self._hosts.add(canonicalize_hostname(host))
        except HostnameError as exc:
            raise ValueError(f"cannot add unparseable host {host!r}: {exc}") from exc

    @property
    def hosts(self) -> frozenset[str]:
        return frozenset(self._hosts)

    def __len__(self) -> int:
        return len(self._hosts)

    def __contains__(self, canonical_host: str) -> bool:
        return self._matches(canonical_host)

    def _matches(self, canonical_host: str) -> bool:
        """Return whether *canonical_host* is permitted.

        *canonical_host* is already canonicalized by the caller. The allowlist
        permits a host when it lines up with a stored entry.
        """

        return canonical_host in self._hosts


def host_is_allowed(host: str, allowlist: Allowlist) -> bool:
    """Canonicalize *host* and report whether the allowlist permits it.

    Returns ``False`` when the host cannot be canonicalized at all rather than
    raising, so a malformed host is simply not allowed.
    """

    try:
        canonical = canonicalize_hostname(host)
    except HostnameError:
        return False
    return allowlist._matches(canonical)

