from __future__ import annotations

"""Batch helpers around the SSRF guard.

The egress proxy rarely checks a single URL in isolation. A webhook config holds
several callback URLs; an import job carries a list of source URLs; a redirect
chain produces a sequence of targets that each have to clear the same bar. These
helpers run the guard over a collection and summarize the outcome, so a caller
can fail a whole config when any one target would be denied, or follow a redirect
chain only while every hop stays allowed.

None of this changes the decision rules. Each URL goes through the same guard;
the helpers only collect and shape the results.
"""

from dataclasses import dataclass

from allowlist_policy import Allowlist
from decision import GuardDecision
from ssrf_guard import SsrfGuard, check_url


@dataclass(frozen=True)
class BatchResult:
    """Outcome of checking several URLs against one allowlist."""

    decisions: dict[str, GuardDecision]

    @property
    def all_allowed(self) -> bool:
        return all(d.allowed for d in self.decisions.values())

    @property
    def denied_urls(self) -> list[str]:
        return [url for url, d in self.decisions.items() if not d.allowed]

    def reason_for(self, url: str) -> str | None:
        decision = self.decisions.get(url)
        return decision.reason if decision is not None else None


def check_many(urls: list[str], allowlist: Allowlist) -> BatchResult:
    """Check every URL in *urls* against *allowlist* and collect the decisions."""

    guard = SsrfGuard(allowlist)
    decisions: dict[str, GuardDecision] = {}
    for url in urls:
        decisions[url] = guard.check(url)
    return BatchResult(decisions=decisions)


def first_denied(urls: list[str], allowlist: Allowlist) -> tuple[str, GuardDecision] | None:
    """Return the first ``(url, decision)`` that is denied, or ``None``.

    Useful for a webhook config validator that wants to point the operator at the
    exact callback that failed.
    """

    guard = SsrfGuard(allowlist)
    for url in urls:
        decision = guard.check(url)
        if not decision.allowed:
            return url, decision
    return None


def follow_redirect_chain(chain: list[str], allowlist: Allowlist) -> GuardDecision:
    """Walk a redirect *chain* and return the first denial, else the last allow.

    A redirect is only safe if every hop is allowed. The first hop that fails
    stops the walk and is returned; otherwise the decision for the final hop is
    returned. An empty chain is a missing-host denial.
    """

    if not chain:
        return check_url("", allowlist)

    last: GuardDecision | None = None
    for hop in chain:
        last = check_url(hop, allowlist)
        if not last.allowed:
            return last
    assert last is not None
    return last


def build_allowlist(*hosts: str) -> Allowlist:
    """Construct an allowlist from bare hostnames."""

    allowlist = Allowlist()
    for host in hosts:
        allowlist.add(host)
    return allowlist

