from __future__ import annotations

"""Recognizing and classifying IP-literal hosts.

A host token is sometimes not a name at all but an IP address, and an attacker
who wants the service to call something internal will reach for the literal that
points at it: ``127.0.0.1`` for loopback, ``169.254.169.254`` for the cloud
metadata endpoint, ``10.x`` / ``172.16-31.x`` / ``192.168.x`` for private
ranges, and link-local ``169.254.x``.

The hard part is that an HTTP client accepts IPv4 literals written in forms most
checkers never think about. ``inet_aton``-style parsing means all of these dial
``127.0.0.1``::

    127.0.0.1          dotted quad
    2130706433         a single 32-bit decimal
    0x7f000001         a single hex value
    0177.0.0.1         a leading-zero octal first octet
    017700000001       a single octal value

A host that resolves to one of those addresses has to be recognized as an
address and blocked, however it was written. This module turns the recognized
forms into a normalized dotted-quad string and reports whether the resulting
address sits in a blocked range. IPv6 literals are handled for the loopback
(``::1``) and link-local cases as well.
"""

from dataclasses import dataclass


# The single cloud metadata service address every provider parks on link-local.
METADATA_IPV4 = "169.254.169.254"


@dataclass(frozen=True)
class IpClassification:
    """How an IP literal should be treated by the guard."""

    is_ip_literal: bool
    normalized: str | None = None
    is_loopback: bool = False
    is_private: bool = False
    is_link_local: bool = False
    is_metadata: bool = False

    @property
    def is_blocked(self) -> bool:
        return self.is_loopback or self.is_private or self.is_link_local or self.is_metadata


def _parse_ipv4_octets(host: str) -> list[int] | None:
    """Parse *host* into four octets if it is an IPv4 literal.

    Returns ``None`` when *host* is not an IPv4 literal that this parser
    recognizes. Each octet must be a number in ``0..255``.
    """

    if host == "" or any(c.isspace() for c in host):
        return None

    parts = host.split(".")
    if len(parts) > 4:
        return None

    values: list[int] = []
    for part in parts:
        value = _parse_int_part(part)
        if value is None:
            return None
        values.append(value)

    if len(values) == 4:
        if any(v > 0xFF for v in values):
            return None
        return values

    if not values:
        return None

    *leading, last = values
    if any(v > 0xFF for v in leading):
        return None
    remaining = 4 - len(leading)
    max_last = (1 << (8 * remaining)) - 1
    if last > max_last:
        return None

    octets = list(leading)
    for shift in range(remaining - 1, -1, -1):
        octets.append((last >> (8 * shift)) & 0xFF)
    return octets


def _parse_int_part(part: str) -> int | None:
    """Parse one dotted component into its integer value."""

    if part == "":
        return None
    low = part.lower()
    try:
        if low.startswith("0x"):
            return int(low, 16)
        if low.startswith("0") and len(low) > 1:
            return int(low, 8)
        return int(low, 10)
    except ValueError:
        return None


def _octets_to_dotted(octets: list[int]) -> str:
    return ".".join(str(o) for o in octets)


def _classify_ipv4(octets: list[int]) -> IpClassification:
    normalized = _octets_to_dotted(octets)
    a, b, c, d = octets

    is_metadata = normalized == METADATA_IPV4
    is_loopback = a == 127
    is_link_local = a == 169 and b == 254
    is_private = (
        a == 10
        or (a == 172 and 16 <= b <= 31)
        or (a == 192 and b == 168)
    )

    return IpClassification(
        is_ip_literal=True,
        normalized=normalized,
        is_loopback=is_loopback,
        is_private=is_private,
        is_link_local=is_link_local,
        is_metadata=is_metadata,
    )


def _classify_ipv6(host: str) -> IpClassification | None:
    """Recognize the IPv6 loopback and link-local cases.

    The host arrives without brackets here. Only the cases that matter for SSRF
    blocking are classified; an ordinary global IPv6 literal is reported as an IP
    literal that is not blocked.
    """

    token = host.lower()
    if ":" not in token:
        return None

    compact = token.split("%", 1)[0]  # drop any zone id
    if compact in ("::1", "0:0:0:0:0:0:0:1"):
        return IpClassification(is_ip_literal=True, normalized="::1", is_loopback=True)
    if compact.startswith("fe80:") or compact == "fe80::":
        return IpClassification(is_ip_literal=True, normalized=compact, is_link_local=True)
    # Some clients accept IPv4-mapped IPv6 like ::ffff:127.0.0.1.
    if compact.startswith("::ffff:") and "." in compact:
        mapped = compact.rsplit(":", 1)[-1]
        octets = _parse_ipv4_octets(mapped)
        if octets is not None:
            inner = _classify_ipv4(octets)
            return IpClassification(
                is_ip_literal=True,
                normalized=f"::ffff:{inner.normalized}",
                is_loopback=inner.is_loopback,
                is_private=inner.is_private,
                is_link_local=inner.is_link_local,
                is_metadata=inner.is_metadata,
            )
    return IpClassification(is_ip_literal=True, normalized=compact)


def classify_host(host: str) -> IpClassification:
    """Classify a host token as an IP literal (and which kind) or not.

    Returns a classification with ``is_ip_literal`` ``False`` when the host is a
    name rather than an address. Any blocked range is reported through the
    ``is_*`` flags so the policy layer can pick a precise reason code.
    """

    ipv6 = _classify_ipv6(host)
    if ipv6 is not None:
        return ipv6

    octets = _parse_ipv4_octets(host)
    if octets is not None:
        return _classify_ipv4(octets)

    return IpClassification(is_ip_literal=False)


def is_blocked_ip_literal(host: str) -> bool:
    """True when *host* is an IP literal in a loopback/private/link-local range."""

    return classify_host(host).is_blocked

