from __future__ import annotations

"""The outbound-fetch guard: allow or deny one URL.

This is the single decision point an egress proxy calls before it dials any
user-supplied URL. It strings the layers together:

1. Parse the URL into scheme, authority, and tail.
2. Confirm the scheme is one the service is willing to fetch over.
3. Extract the *real* host the client will connect to, out of the authority.
4. If that host is an IP literal, block it when it falls in a loopback,
   private, link-local, or cloud-metadata range — in any spelling.
5. Otherwise canonicalize the name and require an exact allowlist match.

Every failure short-circuits to a :class:`GuardDecision` with a stable reason
code. The host reported on the decision is always the host the guard judged, so
an operator reading the log sees the target the request would really have hit,
not the userinfo or the path.
"""

from allowlist_policy import Allowlist
from decision import (
    GuardDecision,
    REASON_LINK_LOCAL_IP,
    REASON_LOOPBACK_IP,
    REASON_METADATA_IP,
    REASON_PRIVATE_IP,
    allow,
    deny,
)
from decision import (
    REASON_BAD_URL,
    REASON_MISSING_HOST,
    REASON_NOT_ON_ALLOWLIST,
    REASON_UNSUPPORTED_SCHEME,
)
from host_authority import HostAuthority, HostExtractionError, extract_host_authority
from hostname import HostnameError, canonicalize_hostname
from ip_literal import classify_host
from url_model import ParsedUrl, parse_url
from url_text import UrlSyntaxError


DEFAULT_ALLOWED_SCHEMES = ("http", "https")


class SsrfGuard:
    """Decides whether the service may fetch a user-supplied URL."""

    def __init__(
        self,
        allowlist: Allowlist,
        allowed_schemes: tuple[str, ...] = DEFAULT_ALLOWED_SCHEMES,
    ) -> None:
        self.allowlist = allowlist
        self.allowed_schemes = tuple(s.lower() for s in allowed_schemes)

    def check(self, url: str) -> GuardDecision:
        """Return an allow/deny decision for *url*."""

        try:
            parsed = parse_url(url)
        except UrlSyntaxError as exc:
            return deny(REASON_BAD_URL, message=str(exc))

        scheme_decision = self._check_scheme(parsed)
